INSERT INTO survey_template (id, version, name, perspective, source_ref, items_json, scoring_json, rubric_ref, published_at) VALUES ('tpl_mid_level', 2, 'Mid-Level', 'Translation Team', 'klappy/3d-quality-review@f042cde553761a6a7f24132cef7802f956378ee0:rubric_csv/Items.csv+Options.csv', '[{"id":"ML-Q1","group":"Translation Process & Brief","text":"Does the team have a translation brief or plan that defines what kind of translation they are aiming for?","type":"single","required":true,"source_type":"ordinal-scored","source_q_num":1,"source_score_max":100.0,"source_weight_in_subdim":1.0,"source_notes":null,"source_cross_lens_construct":"translation-brief-alignment","standalone_indicator":false,"options":[{"code":"documented","text":"Yes, they have a documented brief that defines their translation type and goals","source_order":1,"source_score":100.0,"weight":null,"flag":null,"source_notes":null},{"code":"shared-undocumented","text":"Yes, they have a shared understanding as a team of what they are aiming for, but it is not documented","source_order":2,"source_score":67.0,"weight":null,"flag":null,"source_notes":null},{"code":"working-on","text":"They are still working on defining their translation type and goals","source_order":3,"source_score":33.0,"weight":null,"flag":null,"source_notes":null},{"code":"other","text":"Other (please describe)","source_order":4,"source_score":null,"weight":null,"flag":"missing","source_notes":"Treat as missing unless inferable."}]},{"id":"ML-Q2","group":"Translation Process & Brief","text":"If the team has a brief, what type of translation does it describe?","type":"single","required":true,"source_type":"descriptive","source_q_num":2,"source_score_max":null,"source_weight_in_subdim":1.0,"source_notes":"Descriptive — captures translation type (filter, not score). Triangulates with CHIP/CHCP/CHDL-Q1.","source_cross_lens_construct":"translation-brief-alignment","standalone_indicator":false,"options":[{"code":"corresponding","text":"Corresponding — very close to the original Greek or Hebrew","source_order":1,"source_score":null,"weight":null,"flag":"descriptive","source_notes":null},{"code":"resembling","text":"Resembling — close to the original with some adjustments for clarity","source_order":2,"source_score":null,"weight":null,"flag":"descriptive","source_notes":null},{"code":"clarifying","text":"Clarifying — focused on understandability in natural language","source_order":3,"source_score":null,"weight":null,"flag":"descriptive","source_notes":null},{"code":"simplifying","text":"Simplifying — easy to understand, using contemporary everyday language","source_order":4,"source_score":null,"weight":null,"flag":"descriptive","source_notes":null},{"code":"other","text":"Other (please describe)","source_order":5,"source_score":null,"weight":null,"flag":"descriptive","source_notes":null}]},{"id":"ML-Q3","group":"Translation Process & Brief","text":"Before drafting, what does the team do to understand the meaning of the passage?","type":"single","required":true,"source_type":"ordinal-scored","source_q_num":3,"source_score_max":100.0,"source_weight_in_subdim":1.0,"source_notes":null,"source_cross_lens_construct":null,"standalone_indicator":false,"options":[{"code":"multi-resources","text":"They study the passage using multiple resources (commentaries, original languages, etc.) and discuss as a team","source_order":1,"source_score":100.0,"weight":null,"flag":null,"source_notes":null},{"code":"one-resource","text":"They study the passage using at least one reference resource","source_order":2,"source_score":67.0,"weight":null,"flag":null,"source_notes":null},{"code":"language-discussion","text":"They read the passage in a language they understand well and discuss it","source_order":3,"source_score":33.0,"weight":null,"flag":null,"source_notes":null},{"code":"existing-understanding","text":"They begin drafting based on their existing understanding","source_order":4,"source_score":0.0,"weight":null,"flag":null,"source_notes":null},{"code":"other","text":"Other (please describe)","source_order":5,"source_score":null,"weight":null,"flag":"missing","source_notes":null}]},{"id":"ML-Q4","group":"Translation Process & Brief","text":"What exegetical resources does the team use regularly?","type":"multi","required":true,"source_type":"multi-capability-scored","source_q_num":4,"source_score_max":100.0,"source_weight_in_subdim":1.0,"source_notes":"Multi-select capability. Weights mirror TR-Q4.","source_cross_lens_construct":null,"standalone_indicator":false,"options":[{"code":"original-lang","text":"Original language texts (Greek/Hebrew)","source_order":1,"source_score":null,"weight":3.0,"flag":null,"source_notes":null},{"code":"interlinear","text":"Interlinear texts","source_order":2,"source_score":null,"weight":2.0,"flag":null,"source_notes":null},{"code":"commentaries","text":"Commentaries","source_order":3,"source_score":null,"weight":2.0,"flag":null,"source_notes":null},{"code":"handbooks","text":"Translation handbooks (e.g., UBS/SIL handbooks)","source_order":4,"source_score":null,"weight":2.0,"flag":null,"source_notes":null},{"code":"back-trans","text":"Back translations from related languages","source_order":5,"source_score":null,"weight":1.0,"flag":null,"source_notes":null},{"code":"national-lang","text":"National language translations","source_order":6,"source_score":null,"weight":1.0,"flag":null,"source_notes":null},{"code":"other-widespread","text":"Other translations in widely spoken languages","source_order":7,"source_score":null,"weight":1.0,"flag":null,"source_notes":null},{"code":"other","text":"Other (please describe)","source_order":8,"source_score":null,"weight":1.0,"flag":"other","source_notes":"Counts at weight 1 — review qualitatively."}]},{"id":"ML-Q5","group":"Translation Process & Brief","text":"How does the team check draft work internally before moving to external review?","type":"single","required":true,"source_type":"ordinal-scored","source_q_num":5,"source_score_max":100.0,"source_weight_in_subdim":1.0,"source_notes":null,"source_cross_lens_construct":null,"standalone_indicator":false,"options":[{"code":"full-team","text":"The full team reviews every draft together","source_order":1,"source_score":100.0,"weight":null,"flag":null,"source_notes":null},{"code":"every-checked","text":"Every draft is checked by at least one other team member before moving forward","source_order":2,"source_score":75.0,"weight":null,"flag":null,"source_notes":null},{"code":"lead-reviews","text":"The lead translator or translation supervisor reviews drafts","source_order":3,"source_score":50.0,"weight":null,"flag":null,"source_notes":null},{"code":"checked-when-questions","text":"Drafts are checked by another team member when there are questions or concerns","source_order":4,"source_score":25.0,"weight":null,"flag":null,"source_notes":null},{"code":"skip-internal","text":"They move directly to external review without internal cross-checking","source_order":5,"source_score":0.0,"weight":null,"flag":null,"source_notes":null},{"code":"other","text":"Other (please describe)","source_order":6,"source_score":null,"weight":null,"flag":"missing","source_notes":null}]},{"id":"ML-Q6","group":"Translation Process & Brief","text":"How does the team gather feedback from community members on draft translations?","type":"single","required":true,"source_type":"ordinal-scored","source_q_num":6,"source_score_max":100.0,"source_weight_in_subdim":1.0,"source_notes":"Middle three options are different approaches at roughly equivalent quality — scored equal.","source_cross_lens_construct":null,"standalone_indicator":false,"options":[{"code":"structured-rep","text":"They have a structured process for regularly gathering feedback from a representative group of community members","source_order":1,"source_score":100.0,"weight":null,"flag":null,"source_notes":null},{"code":"informal-occasional","text":"They gather feedback from community members informally and occ